        let r2 = vec![Complex::new(1.0_f32, 0.0); 3];
        let r3 = vec![Complex::new(1.0_f32, 0.0); 4];
        let err = compute_coherence_from_realizations(&[r0, r1, r2, r3]).unwrap_err();
        assert!(err.contains("has 4 bins, expected 3"), "got: {err}");
